/* ACC rankings use the same public leaderboard and scoring as the established site. */
(() => {
  const root = document.querySelector('#ranking-app');
  if (!root) return;
  const content = document.querySelector('#ranking-content');
  const language = document.documentElement.lang;
  const copy = {
    fr:{loading:'Chargement du classement…',error:'Le classement est momentanément indisponible.',empty:'Aucune donnée publiée.',driver:'Pilote',points:'Points',races:'Courses',wins:'Victoires',podiums:'Podiums',pace:'Rythme et progression',next:'Prochain objectif',maximum:'Niveau maximal',first:'Premiers chronos requis',circuit:'Circuit',car:'Voiture',lap:'Meilleur tour',performance:'Performance',team:'Équipe',drivers:'Pilotes',average:'Indice moyen',select:'Choisir un pilote',reference:'Tour de référence',view:'Voir le profil',categories:'Catégories de course',all:'Toutes catégories',legends:['Rookie · 106%+','Pro · 104–105,99%','Elite · 102–103,99%','Alien · 100–101,99%'],fp:'Essais libres',qualifying:'Qualifications',race:'Course',circuits:'Circuits',target:'Objectif',name:'Nom'},
    en:{loading:'Loading standings…',error:'The standings are temporarily unavailable.',empty:'No published results yet.',driver:'Driver',points:'Points',races:'Races',wins:'Wins',podiums:'Podiums',pace:'Pace and progression',next:'Next target',maximum:'Top level',first:'First lap times needed',circuit:'Circuit',car:'Car',lap:'Best lap',performance:'Performance',team:'Team',drivers:'Drivers',average:'Average pace',select:'Choose a driver',reference:'Reference lap',view:'View profile',categories:'Race categories',all:'All categories',legends:['Rookie · 106%+','Pro · 104–105.99%','Elite · 102–103.99%','Alien · 100–101.99%'],fp:'Practice',qualifying:'Qualifying',race:'Race',circuits:'Circuits',target:'Target',name:'Name'},
    de:{loading:'Wertung wird geladen…',error:'Die Wertung ist vorübergehend nicht verfügbar.',empty:'Noch keine veröffentlichten Ergebnisse.',driver:'Fahrer',points:'Punkte',races:'Rennen',wins:'Siege',podiums:'Podien',pace:'Tempo und Entwicklung',next:'Nächstes Ziel',maximum:'Höchste Stufe',first:'Erste Rundenzeiten nötig',circuit:'Strecke',car:'Fahrzeug',lap:'Beste Runde',performance:'Leistung',team:'Team',drivers:'Fahrer',average:'Durchschnittstempo',select:'Fahrer wählen',reference:'Referenzrunde',view:'Profil ansehen',categories:'Rennkategorien',all:'Alle Kategorien',legends:['Rookie · ab 106 %','Pro · 104–105,99 %','Elite · 102–103,99 %','Alien · 100–101,99 %'],fp:'Training',qualifying:'Qualifikation',race:'Rennen',circuits:'Strecken',target:'Ziel',name:'Name'},
    it:{loading:'Caricamento classifica…',error:'La classifica è temporaneamente non disponibile.',empty:'Nessun risultato pubblicato.',driver:'Pilota',points:'Punti',races:'Gare',wins:'Vittorie',podiums:'Podi',pace:'Ritmo e progressione',next:'Prossimo obiettivo',maximum:'Livello massimo',first:'Servono i primi tempi',circuit:'Circuito',car:'Auto',lap:'Miglior giro',performance:'Prestazione',team:'Squadra',drivers:'Piloti',average:'Ritmo medio',select:'Scegli un pilota',reference:'Giro di riferimento',view:'Vedi profilo',categories:'Categorie di gara',all:'Tutte le categorie',legends:['Rookie · 106%+','Pro · 104–105,99%','Elite · 102–103,99%','Alien · 100–101,99%'],fp:'Prove libere',qualifying:'Qualifiche',race:'Gara',circuits:'Circuiti',target:'Obiettivo',name:'Nome'},
    es:{loading:'Cargando clasificación…',error:'La clasificación no está disponible temporalmente.',empty:'Aún no hay resultados publicados.',driver:'Piloto',points:'Puntos',races:'Carreras',wins:'Victorias',podiums:'Podios',pace:'Ritmo y progreso',next:'Próximo objetivo',maximum:'Nivel máximo',first:'Faltan tiempos de vuelta',circuit:'Circuito',car:'Coche',lap:'Mejor vuelta',performance:'Rendimiento',team:'Equipo',drivers:'Pilotos',average:'Ritmo medio',select:'Elegir piloto',reference:'Vuelta de referencia',view:'Ver perfil',categories:'Categorías de carrera',all:'Todas las categorías',legends:['Rookie · 106%+','Pro · 104–105,99%','Elite · 102–103,99%','Alien · 100–101,99%'],fp:'Entrenamientos',qualifying:'Clasificación',race:'Carrera',circuits:'Circuitos',target:'Objetivo',name:'Nombre'}
  }[language] || {};
  const endpoint = 'https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/public-leaderboard';
  const base = document.querySelector('meta[name="atx-base"]')?.content || '/atxracing/';
  const validCategories = ['WGT','DR','BA'];
  const query = new URLSearchParams(location.search);
  let category = validCategories.includes(query.get('type')?.toUpperCase()) ? query.get('type').toUpperCase() : 'DR';
  let view = ['points','circuit','driver','team'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'points';
  const cache = new Map();
  let renderSequence = 0;
  const el = (tag, className, value) => {const x=document.createElement(tag);if(className)x.className=className;if(value!==undefined)x.textContent=String(value);return x};
  const append = (parent, ...children) => {parent.append(...children);return parent};
  const format = n => Number(n||0).toLocaleString(language,{maximumFractionDigits:1});
  const percent = n => Number(n).toLocaleString(language,{minimumFractionDigits:2,maximumFractionDigits:2})+'%';
  const lap = ms => ms>0 ? `${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}.${String(ms%1000).padStart(3,'0')}` : '—';
  const tier = t => ['rookie','pro','elite','alien'].includes(t) ? t : 'unranked';
  const progress = (t,n) => !Number.isFinite(n) ? 0 : t==='alien'?100:t==='elite'?Math.max(0,Math.min(100,(104-n)/2*100)):t==='pro'?Math.max(0,Math.min(100,(106-n)/2*100)):Math.max(0,Math.min(100,(112-Math.min(n,112))/6*100));
  const target = t => ({rookie:'Pro · 105.99%',pro:'Elite · 103.99%',elite:'Alien · 101.99%',alien:copy.maximum})[t]||copy.first;
  function avatar(driver){const wrap=el('span','ranking-avatar');const url=String(driver.avatar_url||'');if(/^https:\/\//.test(url)){const image=el('img');image.src=url;image.alt='';image.loading='lazy';image.referrerPolicy='no-referrer';image.onerror=()=>wrap.replaceChildren(el('span','',String(driver.display_name||'AT').slice(0,2).toUpperCase()));wrap.append(image)}else wrap.textContent=String(driver.display_name||'AT').slice(0,2).toUpperCase();return wrap}
  function driverLink(driver){const name=el(driver.profile_id?'a':'strong','ranking-name',driver.display_name||'—');if(driver.profile_id)name.href=base+language+'/acc/profile.html?driver='+encodeURIComponent(driver.profile_id);return append(el('span','ranking-driver'),avatar(driver),name)}
  function meter(value,kind){const rail=el('span','ranking-meter '+kind);rail.setAttribute('role','progressbar');rail.setAttribute('aria-valuemin','0');rail.setAttribute('aria-valuemax','100');rail.setAttribute('aria-valuenow',String(Math.round(value)));const fill=el('i');fill.style.width=Math.max(0,Math.min(100,value))+'%';rail.append(fill);return rail}
  function gridTable(headers,rows,cls){const wrap=el('div','ranking-table-wrap'),t=el('table','ranking-table '+cls),thead=el('thead'),header=el('tr'),tbody=el('tbody');headers.forEach(x=>header.append(el('th','',x)));thead.append(header);rows.forEach(cells=>{const row=el('tr');cells.forEach(value=>{const cell=el('td');cell.append(value instanceof Node?value:document.createTextNode(String(value??'—')));row.append(cell)});tbody.append(row)});t.append(thead,tbody);wrap.append(t);return wrap}
  const empty = ()=>el('p','empty',copy.empty);
  async function fetchRanking(scope){if(cache.has(scope))return cache.get(scope);const request=fetch(endpoint+'?category='+encodeURIComponent(scope),{signal:AbortSignal.timeout(12000)}).then(r=>{if(!r.ok)throw Error(r.status);return r.json()});cache.set(scope,request);request.catch(()=>cache.delete(scope));return request}
  function categories(){const nav=el('nav','ranking-categories');nav.setAttribute('aria-label',copy.categories);[['WGT','WorldGT'],['DR','Daily Race'],['BA','Ballade ATX']].forEach(([code,label])=>{const b=el('button','ranking-category');b.type='button';b.dataset.category=code;b.append(el('strong','',code==='BA'?'BALLADE ATX':code),el('small','',label));b.addEventListener('click',()=>{category=code;const q=new URLSearchParams(location.search);q.set('type',code);history.replaceState(null,'',location.pathname+'?'+q+'#'+view);render()});nav.append(b)});return nav}
  function legend(){const row=el('div','ranking-legend');['rookie','pro','elite','alien'].forEach((name,i)=>{const b=el('span','tier-'+name,copy.legends[i]);row.append(b)});return row}
  function paceCell(d){const t=tier(d.performance_class),box=el('div','pace-cell'),head=el('div','pace-head'),badge=el('b','tier-badge tier-'+t,t.toUpperCase()),score=Number(d.performance_score),trend=Number(d.progression);head.append(badge,el('strong','',Number.isFinite(score)&&d.performance_score!=null?percent(score):'—'));if(d.progression!=null&&Math.abs(trend)>.005){const movement=el('span','trend '+(trend>0?'gain':'loss'),(trend>0?'↑ ':'↓ ')+percent(Math.abs(trend)));head.append(movement)}box.append(head,meter(progress(t,score),'pace'),el('small','pace-target',copy.next+' : '+target(t)));return box}
  function safeCell(d){const n=Number(d.safety_score),box=el('div','safe-cell');if(d.safety_class)box.append(el('b','safe-badge safe-'+d.safety_class,d.safety_class.toUpperCase()));if(d.safety_score!=null&&Number.isFinite(n)){box.append(meter(n,'safe'),el('small','',Math.round(n)+' / 100'))}else if(!d.safety_class)box.textContent='—';return box}
  function points(data){const section=el('section','rank-panel');section.append(categories(),legend());const drivers=data.drivers||[];section.append(drivers.length?gridTable(['#',copy.driver,copy.points,copy.races,copy.wins,copy.podiums,copy.pace,'SAFE'],drivers.map(d=>[el('strong','position',d.rank),driverLink(d),format(d.points),format(d.races),format(d.wins),format(d.podiums),paceCell(d),safeCell(d)]),'points-table'):empty());return section}
  function circuit(data){const section=el('section','rank-panel'),circuits=(data.circuits||[]).filter(c=>c.drivers?.length);if(!circuits.length)return section.append(empty()),section;const chooser=el('div','circuit-chooser'),detail=el('div');function show(c){chooser.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.key===c.circuit_key)));const heading=el('div','circuit-heading');heading.append(append(el('div'),el('small','meta',copy.circuit),el('h2','',c.circuit_name)),append(el('div'),el('small','meta',copy.reference),el('strong','',lap(c.reference_lap_ms))));detail.replaceChildren(heading,gridTable(['#',copy.driver,copy.car,copy.lap,copy.performance],c.drivers.map((d,i)=>[i+1,driverLink(d),d.car_model_name||'—',lap(d.best_lap_ms),d.pace_percent!=null?percent(d.pace_percent):'—']),'circuit-table'))}circuits.forEach((c,i)=>{const b=el('button','circuit-choice',c.circuit_name);b.type='button';b.dataset.key=c.circuit_key;b.onclick=()=>show(c);chooser.append(b)});section.append(chooser,detail);show(circuits[0]);return section}
  function driver(data){const section=el('section','rank-panel'),drivers=(data.drivers||[]).filter(d=>d.profile_id);if(!drivers.length)return section.append(empty()),section;const label=el('label','driver-select',copy.select+' '),select=el('select'),detail=el('div');drivers.forEach(d=>{const option=el('option','',d.display_name);option.value=d.driver_id;select.append(option)});function show(){const d=drivers.find(item=>item.driver_id===select.value),card=el('div','driver-summary');if(!d)return;card.append(driverLink(d),paceCell(d),safeCell(d));const circuits=(data.circuits||[]).flatMap(c=>{const result=c.drivers?.find(x=>x.driver_id===d.driver_id);return result?[{c,result}]:[]});detail.replaceChildren(card,circuits.length?gridTable([copy.circuit,copy.car,copy.lap,copy.fp,copy.qualifying,copy.race],circuits.map(({c,result:r})=>[c.circuit_name,r.car_model_name||'—',lap(r.best_lap_ms),lap(r.session_laps?.FP),lap(r.session_laps?.Q),lap(r.session_laps?.R)]),'driver-table'):empty())}select.onchange=show;label.append(select);section.append(label,detail);show();return section}
  function team(data){const section=el('section','rank-panel'),teams=data.teams||[];section.append(teams.length?gridTable(['#',copy.team,copy.points,copy.drivers,copy.races,copy.wins,copy.podiums,copy.average],teams.map(d=>[d.rank,d.team_name,format(d.points),d.drivers,d.races,d.wins,d.podiums,d.performance_score!=null?percent(d.performance_score):'—']),'team-table'):empty());return section}
  async function render(){const sequence=++renderSequence;root.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.setAttribute('aria-current',active?'page':'false')});content.replaceChildren(el('p','loading',copy.loading));try{const data=await fetchRanking(view==='points'||view==='team'?category:'ALL');if(sequence!==renderSequence)return;content.replaceChildren(({points,circuit,driver,team})[view](data));content.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===category)))}catch(error){if(sequence===renderSequence)content.replaceChildren(el('p','empty',copy.error))}}
  root.querySelectorAll('[data-view]').forEach(b=>{b.addEventListener('click',()=>{view=b.dataset.view;history.replaceState(null,'',location.pathname+location.search+'#'+view);render()})});
  window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['points','circuit','driver','team'].includes(next)){view=next;render()}});
  render();
})();
